"use client";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { DollarSign, Users, Activity, Target, ArrowUpRight, Search, Bell } from "lucide-react";
import Link from "next/link";

interface DashboardStats {
  recuperado_mes: number;
  pendente_total: number;
  taxa_conversao_robo: number;
  ativos_fila: number;
}

interface FilaItem {
  id: number;
  cliente: string;
  telefone: string;
  dias_atraso: number;
  valor_total: number;
  score: "ALTO" | "MEDIO" | "BAIXO";
  ultima_acao: string;
  status: string;
}

export default function AdminDashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [fila, setFila] = useState<FilaItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Fetch data from FastAPI backend
    const fetchData = async () => {
      try {
        const statsRes = await fetch("http://localhost:8000/admin/dashboard-stats");
        const filaRes = await fetch("http://localhost:8000/admin/fila-inteligente");
        
        if (statsRes.ok && filaRes.ok) {
          setStats(await statsRes.json());
          setFila(await filaRes.json());
        }
      } catch (error) {
        console.error("Error fetching data:", error);
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, []);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);

  return (
    <div className="min-h-screen p-4 md:p-8">
      {/* Header */}
      <header className="flex items-center justify-between mb-8 max-w-7xl mx-auto">
        <div className="flex items-center gap-4">
          <Link href="/">
            <div className="w-10 h-10 rounded-xl bg-indigo-500/20 flex items-center justify-center border border-indigo-500/30 text-indigo-400 font-bold text-xl cursor-pointer">
              R+
            </div>
          </Link>
          <div>
            <h1 className="text-xl font-bold">Admin Dashboard</h1>
            <p className="text-sm text-zinc-400">Recupera+ Cloud Analytics</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button className="p-2 rounded-full bg-zinc-900 border border-zinc-800 text-zinc-400 hover:text-white transition-colors">
            <Search className="w-5 h-5" />
          </button>
          <button className="p-2 rounded-full bg-zinc-900 border border-zinc-800 text-zinc-400 hover:text-white transition-colors relative">
            <Bell className="w-5 h-5" />
            <span className="absolute top-1 right-1 w-2 h-2 bg-indigo-500 rounded-full"></span>
          </button>
          <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 border-2 border-zinc-950"></div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto space-y-8">
        {loading ? (
          <div className="flex justify-center items-center h-64">
            <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-indigo-500"></div>
          </div>
        ) : (
          <>
            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <Card 
                title="Recuperado (Mês)" 
                value={formatCurrency(stats?.recuperado_mes || 0)}
                icon={<DollarSign className="text-emerald-400 w-5 h-5" />}
                trend="+14.5%"
                delay={0.1}
              />
              <Card 
                title="Pendente (Total)" 
                value={formatCurrency(stats?.pendente_total || 0)}
                icon={<Activity className="text-rose-400 w-5 h-5" />}
                trend="-2.4%"
                trendDown
                delay={0.2}
              />
              <Card 
                title="Conversão do Robô" 
                value={`${stats?.taxa_conversao_robo || 0}%`}
                icon={<Target className="text-indigo-400 w-5 h-5" />}
                trend="+5.2%"
                delay={0.3}
              />
              <Card 
                title="Fila de Ativos" 
                value={stats?.ativos_fila || 0}
                icon={<Users className="text-amber-400 w-5 h-5" />}
                delay={0.4}
              />
            </div>

            {/* Smart Queue */}
            <motion.div 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.5 }}
              className="glass-panel p-6"
            >
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-lg font-semibold flex items-center gap-2">
                  <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></span>
                  Fila Inteligente de Cobrança
                </h2>
                <button className="text-sm text-indigo-400 hover:text-indigo-300 font-medium">
                  Ver Todos
                </button>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="border-b border-white/5 text-zinc-400 text-sm">
                      <th className="pb-3 font-medium px-4">Cliente</th>
                      <th className="pb-3 font-medium px-4">Atraso</th>
                      <th className="pb-3 font-medium px-4">Valor Total</th>
                      <th className="pb-3 font-medium px-4">Score</th>
                      <th className="pb-3 font-medium px-4">Status</th>
                      <th className="pb-3 font-medium px-4 text-right">Ação</th>
                    </tr>
                  </thead>
                  <tbody>
                    {fila.map((item, i) => (
                      <motion.tr 
                        key={item.id}
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ duration: 0.3, delay: 0.6 + (i * 0.1) }}
                        className="border-b border-white/5 hover:bg-white/5 transition-colors group"
                      >
                        <td className="py-4 px-4">
                          <div className="font-medium text-white">{item.cliente}</div>
                          <div className="text-xs text-zinc-500">{item.telefone}</div>
                        </td>
                        <td className="py-4 px-4 text-zinc-300">
                          <span className={`px-2 py-1 rounded-md text-xs ${item.dias_atraso > 90 ? 'bg-rose-500/10 text-rose-400' : 'bg-amber-500/10 text-amber-400'}`}>
                            {item.dias_atraso} dias
                          </span>
                        </td>
                        <td className="py-4 px-4 font-medium text-white">{formatCurrency(item.valor_total)}</td>
                        <td className="py-4 px-4">
                          <ScoreBadge score={item.score} />
                        </td>
                        <td className="py-4 px-4 text-zinc-400 text-sm">{item.status}</td>
                        <td className="py-4 px-4 text-right">
                          <button className="text-indigo-400 opacity-0 group-hover:opacity-100 transition-opacity hover:text-white p-2 hover:bg-white/10 rounded-lg">
                            <ArrowUpRight className="w-4 h-4" />
                          </button>
                        </td>
                      </motion.tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </motion.div>
          </>
        )}
      </main>
    </div>
  );
}

function Card({ title, value, icon, trend, trendDown, delay }: any) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay }}
      className="glass-card p-5 flex flex-col gap-4"
    >
      <div className="flex justify-between items-start">
        <p className="text-sm font-medium text-zinc-400">{title}</p>
        <div className="p-2 rounded-lg bg-zinc-800/50">
          {icon}
        </div>
      </div>
      <div className="flex items-end justify-between">
        <h3 className="text-2xl font-bold text-white tracking-tight">{value}</h3>
        {trend && (
          <span className={`text-xs font-medium px-2 py-1 rounded-md ${trendDown ? 'bg-emerald-500/10 text-emerald-400' : 'bg-emerald-500/10 text-emerald-400'}`}>
            {trend}
          </span>
        )}
      </div>
    </motion.div>
  );
}

function ScoreBadge({ score }: { score: string }) {
  const colors = {
    ALTO: "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20",
    MEDIO: "bg-amber-500/10 text-amber-400 border border-amber-500/20",
    BAIXO: "bg-rose-500/10 text-rose-400 border border-rose-500/20"
  };
  
  return (
    <span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${(colors as any)[score] || colors.MEDIO}`}>
      {score}
    </span>
  );
}
